class Solution:
    def finalPositionOfSnake(self, n: int, commands: List[str]) -> int:
        # Start at position 0, which is (0, 0)
        row, col = 0, 0

        # Process each command
        for command in commands:
            if command == "RIGHT":
                col += 1
            elif command == "LEFT":
                col -= 1
            elif command == "DOWN":
                row += 1
            elif command == "UP":
                row -= 1

        # Convert (row, col) to position using formula: row * n + col
        return row * n + col

class Solution:
    def winningPlayerCount(self, n: int, pick: List[List[int]]) -> int:
        # Group picks by player to count how many balls of each color they picked
        player_picks = {}

        for player, color in pick:
            if player not in player_picks:
                player_picks[player] = {}
            player_picks[player][color] = player_picks[player].get(color, 0) + 1

        # Count how many players win
        win_count = 0

        for player in range(n):
            if player not in player_picks:
                # Player didn't pick any ball, so they can't win
                continue

            # Find the maximum count of any single color for this player
            max_count = max(player_picks[player].values())

            # Player i wins if they pick strictly more than i balls of the same color
            if max_count > player:
                win_count += 1

        return win_count

class Solution:
    def minFlips(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])

        # Calculate flips needed to make all rows palindromic
        rows_flips = 0
        for i in range(m):
            for j in range(n // 2):
                # Compare position j with position (n-1-j)
                if grid[i][j] != grid[i][n - 1 - j]:
                    rows_flips += 1

        # Calculate flips needed to make all columns palindromic
        cols_flips = 0
        for j in range(n):
            for i in range(m // 2):
                # Compare position i with position (m-1-i)
                if grid[i][j] != grid[m - 1 - i][j]:
                    cols_flips += 1

        # Return minimum of the two options
        return min(rows_flips, cols_flips)

