    strings.append(input().strip())

# Find maximum length
m = max(len(s) for s in strings)

# Create vertical strings
for j in range(1, m + 1):
    t_j = ""
    # Go through strings in reverse order (N down to 1)
    for i in range(n - 1, -1, -1):
        if j <= len(strings[i]):
            t_j += strings[i][j - 1]
        else:
            t_j += '*'

    # Remove trailing '*' (but keep at least one character)
    while t_j and t_j[-1] == '*':
        t_j = t_j[:-1]

